type WorkerTask={id:number;kind:'tile';request:SurfaceTileRequest}|{id:number;kind:'mesh';tile:GeoTile;resolution:number;radiusM:number;coarseEdgeMask:number};
const scope=self as unknown as {onmessage:((event:MessageEvent<WorkerTask>)=>void)|null;postMessage:(value:unknown,transfer?:Transferable[])=>void};
